CREATE FUNCTION public.next_takip_no() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v int;
begin
  update public.takip_counter
     set next_no = next_no + 1
   where id = 1
   returning next_no - 1 into v;
  if v is null then
    insert into public.takip_counter (id, next_no) values (1, 1002)
      on conflict (id) do update set next_no = public.takip_counter.next_no + 1
      returning next_no - 1 into v;
  end if;
  return v;
end $$;

CREATE FUNCTION public.project_render_context(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_strip_nulls(
    coalesce(pr.input_data, '{}'::jsonb)
    || jsonb_build_object(
      'dosya_no',       pr.dosya_no,
      'dosya_tarihi',   pr.dosya_tarihi,
      'durum',          pr.status,
      'il',             prov.name,
      'belediye',       dist.name,
      'modul',          pr.certification_module,
      'beyan_yuku_kg',  pr.beyan_yuku_kg,
      'kisi_sayisi',    pr.kisi_sayisi,
      'beyan_hizi',     pr.beyan_hizi,
      'kat_adedi',      pr.kat_adedi,
      'durak_adedi',    pr.durak_adedi,
      'imal_yili',      pr.imal_yili,
      'firma', (
        select jsonb_build_object(
          'unvan', c.legal_name, 'kisa_ad', c.short_name, 'adres', c.address,
          'telefon', c.phone, 'faks', c.fax, 'sehir', c.city,
          'yetkili', c.authorized_person, 'tescilli_marka', c.registered_brand,
          'sanayi_sicil_no', c.industry_reg_no, 'sanayi_sicil_tarih', c.industry_reg_date,
          'hyb_tarih', c.hyb_date)
        from public.companies c where c.id = pr.company_id
      ),
      'firma_modul', (
        select jsonb_build_object(
          'belge_no', cmc.belge_no, 'tarih', cmc.issue_date,
          'onaylanmis_kurulus', nb.name, 'kurulus_no', nb.identity_no)
        from public.company_module_certs cmc
        left join public.notified_bodies nb on nb.id = cmc.notified_body_id
        where cmc.company_id = pr.company_id
          and cmc.module_type = pr.certification_module
      ),
      'muhendis', jsonb_build_object(
        'elektrik', (
          select jsonb_build_object('ad', e.full_name, 'unvan', e.title, 'oda_sicil', e.chamber_reg_no,
                                    'adres', e.address, 'telefon', e.phone)
          from public.engineers e where e.id = pr.elektrik_muhendis_id),
        'makine', (
          select jsonb_build_object('ad', e.full_name, 'unvan', e.title, 'oda_sicil', e.chamber_reg_no,
                                    'adres', e.address, 'telefon', e.phone)
          from public.engineers e where e.id = pr.makine_muhendis_id)
      ),
      'kapasite', (
        select jsonb_build_object('kisi', ct.kisi_sayisi,
          'kabin_agirlik', ct.kabin_agirlik_kg, 'karsi_agirlik', ct.karsi_agirlik_kg)
        from public.capacity_table ct where ct.beyan_yuku_kg = pr.beyan_yuku_kg
      ),
      'ekipman', (
        select coalesce(jsonb_object_agg(
                 ec.code || case when pe.slot <> 'main' then '_' || pe.slot else '' end,
                 elem), '{}'::jsonb)
        from public.project_equipment pe
        join public.equipment_categories ec on ec.id = pe.category_id
        left join public.equipment_brands  b  on b.id = pe.brand_id
        left join public.equipment_models  m  on m.id = pe.model_id
        left join public.certificates      ce on ce.id = pe.certificate_id
        left join public.notified_bodies   nb on nb.id = ce.notified_body_id
        cross join lateral (
          select jsonb_build_object(
            'slot', pe.slot, 'marka', b.name, 'model', m.name,
            'seri_no', pe.seri_no,
            'seri_list', pe.seri_list,
            'sertifika_no', ce.cert_no,
            'onaylanmis_kurulus', nb.name, 'kurulus_no', nb.identity_no) as elem
        ) x
        where pe.project_id = pr.id
      )
    )
  )
  from public.projects pr
  left join public.provinces prov on prov.id = pr.province_id
  left join public.districts dist on dist.id = pr.district_id
  where pr.id = p_id;
$$;

