CREATE VIEW public.v_equipment_catalog AS
 SELECT c.code AS category_code,
    c.name AS category_name,
    b.id AS brand_id,
    b.name AS brand_name,
    m.id AS model_id,
    m.name AS model_name,
    ce.cert_no AS certificate_no,
    nb.identity_no AS notified_body_no,
    nb.name AS notified_body_name,
    cf.storage_path AS certificate_current_file
   FROM (((((public.equipment_categories c
     JOIN public.equipment_brands b ON (((b.category_id = c.id) AND b.is_active)))
     JOIN public.equipment_models m ON (((m.brand_id = b.id) AND m.is_active)))
     LEFT JOIN public.certificates ce ON ((ce.id = m.certificate_id)))
     LEFT JOIN public.notified_bodies nb ON ((nb.id = ce.notified_body_id)))
     LEFT JOIN public.certificate_files cf ON (((cf.certificate_id = ce.id) AND cf.is_current)));

CREATE VIEW public.v_project_overview AS
 SELECT pr.id,
    pr.dosya_no,
    pr.status,
    pr.created_at,
    c.short_name AS firma,
    p.name AS il,
    pr.beyan_yuku_kg,
    pr.kat_adedi,
    pr.durak_adedi,
    cb.full_name AS olusturan,
    ( SELECT count(*) AS count
           FROM public.generated_files gf
          WHERE (gf.project_id = pr.id)) AS uretilen_dosya,
    ( SELECT max(gf.generated_at) AS max
           FROM public.generated_files gf
          WHERE (gf.project_id = pr.id)) AS son_uretim
   FROM (((public.projects pr
     JOIN public.companies c ON ((c.id = pr.company_id)))
     LEFT JOIN public.provinces p ON ((p.id = pr.province_id)))
     LEFT JOIN public.profiles cb ON ((cb.id = pr.created_by)));

